<?php

declare(strict_types=1);namespace App\Controllers;
use App\Core\Auth;use App\Core\Csrf;use App\Core\HttpError;use App\Core\View;use App\Models\CoachCareerEntry;use App\Models\CoachProfile;use App\Models\FootballIdentity;use App\Models\User;use RuntimeException;use Throwable;
final class CoachController
{
 public function index(): void{$filters=['province'=>trim((string)($_GET['province']??'')),'district'=>trim((string)($_GET['district']??'')),'public_title'=>trim((string)($_GET['public_title']??'')),'license_level'=>trim((string)($_GET['license_level']??'')),'intent'=>trim((string)($_GET['intent']??'')),'specialty'=>trim((string)($_GET['specialty']??'')),'verified'=>isset($_GET['verified'])?1:0];$rows=[];try{$rows=CoachProfile::search($filters);}catch(Throwable){}View::render('coaches/index',['title'=>'Teknik Direktörler','coaches'=>$rows,'filters'=>$filters]);}
 public function show(array $params): void{$p=null;try{$p=CoachProfile::findPublicBySlug(trim((string)($params['slug']??'')));}catch(Throwable){}if(!$p){HttpError::render(404,'Teknik direktör profili bulunamadı.');return;}View::render('coaches/show',['title'=>(string)$p['display_name'].' - '.(string)$p['public_title'],'coachProfile'=>$p,'coach'=>$p]);}
 public function form(): void{Auth::requireLogin();$uid=(int)Auth::id();FootballIdentity::syncForUser($uid,['coach'],'coach');$p=null;$identity=[];try{$p=CoachProfile::forOwner($uid);$identity=User::profileIdentity($uid)?:[];}catch(Throwable){}$form=$p?:['province'=>$identity['province']??'','district'=>$identity['district']??'','public_title'=>'Teknik Direktör','license_level'=>'','license_status'=>'unverified','intent'=>'showcase','specialties'=>[],'formations'=>[],'bio'=>'','achievements_text'=>'','status'=>'draft','career'=>[]];View::render('coaches/form',['title'=>'Teknik Direktör Profilim','profile'=>$form,'careerRows'=>$p['career']??[],'errors'=>[]]);}
 public function save(): void{Auth::requireLogin();if(!Csrf::validate($_POST['_csrf']??null)){HttpError::render(419);return;}$submit=(string)($_POST['action']??'draft')==='submit';$career=is_array($_POST['career']??null)?$_POST['career']:[];$errors=CoachProfile::validateInput($_POST)+CoachCareerEntry::validateRows($career);if($errors!==[]){$d=$_POST;$d['specialties']=CoachProfile::normalizeList($_POST['specialties']??[]);$d['formations']=CoachProfile::normalizeList($_POST['formations']??[]);View::render('coaches/form',['title'=>'Teknik Direktör Profilim','profile'=>$d,'careerRows'=>$career,'errors'=>$errors]);return;}try{CoachProfile::save((int)Auth::id(),$_POST,$career,$submit);$_SESSION['flash_success']=$submit?'Teknik direktör profilin moderasyona gönderildi.':'Teknik direktör profilin taslak olarak kaydedildi.';}catch(RuntimeException $e){$_SESSION['flash_error']=$e->getMessage();}catch(Throwable){$_SESSION['flash_error']='Teknik direktör profili kaydedilemedi.';}header('Location: /teknik-direktor-profilim');}
}
